export function slugForProduct(productId) {
  const row = SLUG_MAP.find((s) => s.productId === productId);
  return row ? row.slug : null;
}

export function buildMeta(product) {
  const t = SEO_TEMPLATES[0];
  return {
    title: t.titleTemplate.replace("{{name}}", product?.name || ""),
    description: t.descriptionTemplate.replace("{{tagline}}", product?.tagline || "").replace("{{category}}", product?.category || ""),
  };
}
